package ru.koren.identity;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;
import ru.koren.identity.InvalidInitDataException.Reason;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Crypto vectors were generated by an INDEPENDENT tool: a python3 script using only
 * hashlib/hmac implementing https://dev.max.ru/docs/webapps/validation
 * (secret = HMAC_SHA256("WebAppData", token); hash = hex HMAC_SHA256(secret, check-string)
 * over url-decoded values sorted by key). No Java code under test produced these constants.
 */
class MaxInitDataValidatorTest {

    private static final String TOKEN = "k1-test-bot-token:not-a-real-secret";
    private static final long NOW = 1_800_000_000L;
    private static final Clock FIXED = Clock.fixed(Instant.ofEpochSecond(NOW), ZoneOffset.UTC);

    private final MaxInitDataValidator validator = new MaxInitDataValidator(TOKEN, FIXED);

    // Keys intentionally out of alphabetical order.
    private static final String BASIC =
            "user=%7B%22id%22%3A424242%2C%22first_name%22%3A%22Max%22%2C%22last_name%22%3A%22User%22"
            + "%2C%22username%22%3Anull%2C%22language_code%22%3A%22ru%22%7D&ip=192.168.0.1"
            + "&auth_date=1800000000&query_id=AAE1YmYAAAAANTmv4t3W0h01"
            + "&hash=fa2ff9a4255c0e16b0e5be5a4bc6bded45aadad37b589cebb251fc95d7080ad4";
    private static final String UNICODE =
            "auth_date=1800000000&chat_title=%D0%A1%D0%B2%D0%B5%D1%82%20%D0%B2%20%D0%BF%D0%BE%D0%B4%D1%8A"
            + "%D0%B5%D0%B7%D0%B4%D0%B5%20%E2%84%965%20%F0%9F%9A%AA&user=%7B%22id%22%3A777000111%2C%22first"
            + "_name%22%3A%22%D0%9C%D0%B0%D1%80%D0%B8%D1%8F%20%F0%9F%8C%9F%22%2C%22last_name%22%3A%22%D0%98"
            + "%D0%B2%D0%B0%D0%BD%D0%BE%D0%B2%D0%B0%22%2C%22language_code%22%3A%22ru%22%7D"
            + "&hash=daeb42e7f590b884842183a530374fe3e1795ee69e71bd10132756ce6b66d692";
    private static final String EQUALS_IN_VALUE =
            "start_param=ref%3Da%3Db&auth_date=1800000000"
            + "&user=%7B%22id%22%3A31337%2C%22first_name%22%3A%22Eq%22%2C%22last_name%22%3Anull%7D"
            + "&hash=b27c3f005d80d8ccfcca2d27e0dc2d5c33f0be1ee3526adf0945cc854d11cc98";
    // Decoded note value is "100%+ok": '%' was encoded as %25, '+' is literal and must not become a space.
    private static final String PLUS_PERCENT =
            "note=100%25+ok&auth_date=1800000000"
            + "&user=%7B%22id%22%3A555%2C%22first_name%22%3A%22Plus%22%7D"
            + "&hash=5321905099a3f507534e44a391141e8ca7e970b2725b512ab5c620b23c2d9899";
    private static final String TIME_NOW =
            "user=%7B%22id%22%3A900001%2C%22first_name%22%3A%22Time%22%7D&auth_date=1800000000"
            + "&hash=18d4fd2eecb77b89e4ac4be18dbbbdfe8bd78f5cdb91d6438a0ba2f50c02f348";
    private static final String TIME_OLD_BOUNDARY = // exactly 5 minutes old: allowed
            "user=%7B%22id%22%3A900001%2C%22first_name%22%3A%22Time%22%7D&auth_date=1799999700"
            + "&hash=3cbb0169419ff70921b5dff65a4380cd4656a511a64cb95c5b433c78551452e4";
    private static final String TIME_FUTURE_BOUNDARY = // exactly +60 seconds: allowed
            "user=%7B%22id%22%3A900001%2C%22first_name%22%3A%22Time%22%7D&auth_date=1800000060"
            + "&hash=3f5edb9ef52d959c7c76f537a23a3c37ba0f8655f7e70746b8cd29f4d36f23f4";
    private static final String TIME_STALE = // 6 minutes old
            "user=%7B%22id%22%3A900001%2C%22first_name%22%3A%22Time%22%7D&auth_date=1799999640"
            + "&hash=0c30f4b3b5c8054a754800fb8b898a4cef77c694c7e5bf74bc0103587723ab8f";
    private static final String TIME_FUTURE = // +5 minutes
            "user=%7B%22id%22%3A900001%2C%22first_name%22%3A%22Time%22%7D&auth_date=1800000300"
            + "&hash=53f3c8c642e4444862fa6be33ca65169abddc020d292a4c1fade7b94fe8f9522";
    private static final String TIME_FUTURE_EDGE = // +61 seconds
            "user=%7B%22id%22%3A900001%2C%22first_name%22%3A%22Time%22%7D&auth_date=1800000061"
            + "&hash=a0483d41a9e3a3de7fdfa505dab7d00c981ac1b1b1bb03bd3bb1c35b94d70543";

    @Test
    void validBasicVector() {
        MaxVerifiedUser user = validator.validate(BASIC);
        assertEquals(424242L, user.maxUserId());
        assertEquals("Max User", user.profile().displayName());
        assertNull(user.profile().username());
        assertNull(user.profile().avatarUrl());
        assertEquals("{\"id\":424242,\"first_name\":\"Max\",\"last_name\":\"User\",\"username\":null,"
                + "\"language_code\":\"ru\"}", user.rawUserJson());
    }

    @Test
    void validUnicodeEmojiVector() {
        MaxVerifiedUser user = validator.validate(UNICODE);
        assertEquals(777000111L, user.maxUserId());
        assertEquals("Мария 🌟 Иванова", user.profile().displayName());
    }

    @Test
    void validValueWithEqualsSign() {
        assertEquals(31337L, validator.validate(EQUALS_IN_VALUE).maxUserId());
    }

    @Test
    void validPlusAndPercentVector() {
        assertEquals(555L, validator.validate(PLUS_PERCENT).maxUserId());
    }

    @Test
    void displayNameFallsBackToFirstNameOnly() {
        assertEquals("Time", validator.validate(TIME_NOW).profile().displayName());
    }

    @Test
    void signedProfileIncludesNormalizedNameUsernameAndHttpsAvatar() {
        MaxVerifiedUser user = validator.validate(SignedProfileFixtures.initData("profile"));
        assertEquals(new MaxProfile("Анна Иванова", "anna_max", "https://images.example.org/max/avatar.png"),
            user.profile());
        assertEquals(424242L, user.maxUserId());
    }

    @Test
    void optionalMissingMalformedAndOversizedProfileFieldsDoNotBlockLogin() {
        for (String fixture : new String[] {"missing", "blank", "wrong_types", "oversized"}) {
            MaxVerifiedUser user = validator.validate(SignedProfileFixtures.initData(fixture));
            assertEquals(424242L, user.maxUserId());
            assertEquals(new MaxProfile(null, null, null), user.profile(), fixture);
        }
    }

    @Test
    void unsafeOptionalAvatarIsIgnoredWithoutRejectingSignedIdentity() {
        for (String kind : new String[] {"http", "relative", "scheme_relative", "javascript", "data",
                "credentials", "no_host", "malformed"}) {
            MaxVerifiedUser user = validator.validate(SignedProfileFixtures.initData("unsafe_" + kind));
            assertEquals(424242L, user.maxUserId());
            assertEquals("Анна", user.profile().displayName());
            assertNull(user.profile().avatarUrl(), kind);
        }
    }

    @Test
    void changingDisplayFieldsWithoutAValidSignatureIsRejected() {
        String signed = SignedProfileFixtures.initData("profile");
        for (String forged : new String[] {signed.replace("anna_max", "mallory"),
                signed.replace("avatar.png", "forged.png")}) {
            assertReason(Reason.SIGNATURE, () -> validator.validate(forged));
        }
    }

    @Test
    void freshTimeBoundariesAreAccepted() {
        assertEquals(900001L, validator.validate(TIME_OLD_BOUNDARY).maxUserId());
        assertEquals(900001L, validator.validate(TIME_FUTURE_BOUNDARY).maxUserId());
    }

    @Test
    void tamperedUserFailsSignature() {
        String forged = BASIC.replace("424242", "999999"); // user id changed, hash left intact
        assertReason(Reason.SIGNATURE, () -> validator.validate(forged));
    }

    @Test
    void tamperedHashFailsSignature() {
        String forged = BASIC.replace("hash=fa", "hash=fb");
        assertReason(Reason.SIGNATURE, () -> validator.validate(forged));
    }

    @Test
    void wrongTokenFailsSignature() {
        var other = new MaxInitDataValidator("another-token:not-a-real-secret", FIXED);
        assertReason(Reason.SIGNATURE, () -> other.validate(BASIC));
    }

    @Test
    void duplicateKeyIsRejected() {
        assertReason(Reason.FORMAT, () -> validator.validate(BASIC + "&ip=10.0.0.1"));
    }

    @Test
    void duplicateHashIsRejected() {
        String secondHash = BASIC.substring(BASIC.indexOf("&hash="));
        assertReason(Reason.FORMAT, () -> validator.validate(BASIC + secondHash));
    }

    @Test
    void missingHashIsRejected() {
        assertReason(Reason.FORMAT, () -> validator.validate(BASIC.substring(0, BASIC.indexOf("&hash="))));
    }

    @Test
    void invalidHexHashIsRejected() {
        String bad = BASIC.replace("fa2ff9a4255c0e16b0e5be5a4bc6bded45aadad37b589cebb251fc95d7080ad4",
                "zz2ff9a4255c0e16b0e5be5a4bc6bded45aadad37b589cebb251fc95d7080ad4");
        assertReason(Reason.FORMAT, () -> validator.validate(bad));
        String odd = BASIC.replace("fa2ff9a4255c0e16b0e5be5a4bc6bded45aadad37b589cebb251fc95d7080ad4", "abc");
        assertReason(Reason.FORMAT, () -> validator.validate(odd));
    }

    @Test
    void malformedPercentEncodingIsRejected() {
        assertReason(Reason.FORMAT, () -> validator.validate("user=%GG&auth_date=1&hash=" + "0".repeat(64)));
        assertReason(Reason.FORMAT, () -> validator.validate("user=%2&auth_date=1&hash=" + "0".repeat(64)));
    }

    @Test
    void emptyAndMalformedInputIsRejected() {
        assertReason(Reason.FORMAT, () -> validator.validate(""));
        assertReason(Reason.FORMAT, () -> validator.validate(null));
        assertReason(Reason.FORMAT, () -> validator.validate("no-equals-segment&hash=" + "0".repeat(64)));
    }

    @Test
    void staleAuthDateIsRejected() {
        assertReason(Reason.TIME, () -> validator.validate(TIME_STALE));
    }

    @Test
    void futureAuthDateIsRejected() {
        assertReason(Reason.TIME, () -> validator.validate(TIME_FUTURE));
        assertReason(Reason.TIME, () -> validator.validate(TIME_FUTURE_EDGE));
    }

    @Test
    void clockControlsFreshness() {
        var later = new MaxInitDataValidator(TOKEN,
                Clock.fixed(Instant.ofEpochSecond(NOW + 600), ZoneOffset.UTC));
        assertReason(Reason.TIME, () -> later.validate(TIME_NOW));
        var earlier = new MaxInitDataValidator(TOKEN,
                Clock.fixed(Instant.ofEpochSecond(NOW - 600), ZoneOffset.UTC));
        assertReason(Reason.TIME, () -> earlier.validate(TIME_NOW));
    }

    @Test
    void exceptionDoesNotLeakTokenOrRawData() {
        for (String input : new String[] {BASIC, BASIC.replace("hash=fa", "hash=fb"), TIME_STALE}) {
            try {
                validator.validate(input);
            } catch (InvalidInitDataException e) {
                assertFalse(e.getMessage().contains(TOKEN));
                assertFalse(e.getMessage().contains("424242"));
                assertFalse(e.getMessage().contains("hash="));
            }
        }
    }

    private static void assertReason(Reason reason, org.junit.jupiter.api.function.Executable action) {
        InvalidInitDataException e = assertThrows(InvalidInitDataException.class, action);
        assertEquals(reason, e.reason());
    }
}
